use crate::aap::caps::state_read;

struct Node;

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        let raw = state_read::get("urls")
            .expect("subscriptions store has no 'urls' entry");

        let urls: Vec<String> = raw
            .lines()
            .map(|l| l.trim())
            .filter(|l| !l.is_empty())
            .map(|l| l.to_string())
            .collect();

        // ensures present(urls): never emit an empty list.
        assert!(!urls.is_empty(), "subscription list is empty");

        SubscriptionList { urls }
    }
}

