```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::state_read;

struct Node;

fn parse(raw: &str) -> Vec<String> {
    raw.split(|c: char| c.is_whitespace() || c == ',')
        .map(|t| t.trim_matches(|c: char| c == '[' || c == ']' || c == '"' || c == '\''))
        .filter(|t| !t.is_empty())
        .map(|t| t.to_string())
        .collect()
}

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        for key in ["urls", "subscriptions", "feeds"] {
            if let Some(raw) = state_read::get(key) {
                let urls = parse(&raw);
                if !urls.is_empty() {
                    return SubscriptionList { urls };
                }
            }
        }
        SubscriptionList { urls: Vec::new() }
    }
}

export!(Node);
